541	const ERROR_PAGE = (message: string): string => `<!doctype html>
542	<html lang="zh-CN"><meta charset="utf-8"><title>Cartwell · 出错了</title>
543	<body style="font-family:system-ui,sans-serif;max-width:40rem;margin:3rem auto;padding:0 1rem">
544	<h1>暂时无法读取商品</h1><p>${escapeHtml(message)}</p><p><a href="/">返回首页重试</a></p></body></html>`;
545	
546	// ---------- HTTP 服务 ----------
547	
548	function respond(res: ServerResponse, status: number, value: unknown, html = false, allow?: string): void {
549	  const body = html ? String(value) : JSON.stringify(value);
550	  const headers: Record<string, string> = {
551	    'content-type': html ? 'text/html; charset=utf-8' : 'application/json; charset=utf-8',
552	    'content-length': String(Buffer.byteLength(body)),
553	  };
554	  if (status === 405 && allow) headers.allow = allow;
555	  res.writeHead(status, headers);
556	  res.end(body);
557	}
558	
559	function readJsonBody(req: IncomingMessage): Promise<unknown> {
560	  return new Promise((resolve, reject) => {
561	    let size = 0;
562	    const chunks: Buffer[] = [];
563	    req.on('data', (chunk: Buffer) => {
564	      size += chunk.length;
565	      if (size > MAX_BODY_BYTES) {
566	        reject(new Error('request body too large'));
567	        req.destroy();
568	        return;
569	      }
570	      chunks.push(chunk);
571	    });
572	    req.on('end', () => {
573	      try {
574	        resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')));
575	      } catch {
576	        reject(new Error('invalid JSON'));
577	      }
578	    });
579	    req.on('error', () => reject(new Error('invalid JSON')));
580	  });
581	}
582	
583	const ALLOWED_METHODS: Record<string, string[]> = {
584	  '/': ['GET'],
585	  '/health': ['GET'],
586	  '/api/products': ['GET', 'POST'],
587	};
588	
589	const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
590	  let route: string;
591	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; } catch { respond(res, 400, { error: 'invalid request path' }); return; }
592	
593	  const allowed = ALLOWED_METHODS[route];
594	  if (!allowed) { respond(res, 404, { error: 'not found' }); return; }
595	  const method = req.method ?? '';
596	  if (!allowed.includes(method)) {
597	    respond(res, 405, { error: 'method not allowed', allowed }, false, allowed.join(', '));
598	    return;
599	  }
600	
601	  if (route === '/health') { respond(res, 200, { status: 'ok', product: PRODUCT }); return; }
602	
603	  if (route === '/' && method === 'GET') {
604	    try {
605	      respond(res, 200, renderPage(readProducts()), true);
606	    } catch {
607	      respond(res, 500, ERROR_PAGE('商品数据暂时无法读取，已有记录未被修改。'), true);
608	    }
609	    return;
610	  }
611	
612	  if (route === '/api/products' && method === 'GET') {
613	    try {
614	      respond(res, 200, { [RESOURCE]: readProducts() });
615	    } catch {
616	      respond(res, 500, { error: 'unable to read products' });
617	    }
618	    return;
619	  }
620	
621	  // POST /api/products
622	  readJsonBody(req).then((input) => {
623	    const result = validateProduct(input);
624	    if (!result.ok) {
625	      respond(res, 400, { error: '商品校验未通过，未创建任何记录', details: result.errors });
626	      return;
627	    }
628	    const product: Product = {
629	      id: randomUUID(),
630	      name: result.name,
631	      specs: result.specs,
632	      createdAt: new Date().toISOString(),
633	    };
634	    try {
635	      const products = readProducts();
636	      products.unshift(product); // 新创建的商品排在最前
637	      saveProducts(products);
638	    } catch {
639	      respond(res, 500, { error: '商品保存失败，请稍后重试；已有商品未受影响' });
640	      return;
641	    }
642	    respond(res, 201, product);
643	  }).catch((error: Error) => {
644	    if (error.message === 'request body too large') {
645	      respond(res, 400, { error: '请求体超过大小限制' });
646	    } else {
647	      respond(res, 400, { error: '请求内容不是合法的 JSON' });
648	    }
649	  });
650	});
651	
652	server.once('error', (error: Error): void => { console.error(error.message); process.exitCode = 1; });
653	server.listen(port, host, (): void => {
654	  const address = server.address();
655	  if (address && typeof address !== 'string') {
656	    const displayedHost = address.address.includes(':') ? `[${address.address}]` : address.address;
657	    console.log(`${PRODUCT} listening on http://${displayedHost}:${address.port}`);
658	  }
659	});
