import http from 'node:http';

const LIMIT = 1_048_576;

function rawRequest(path, payload, { chunked = false, splitAt } = {}) {
  return new Promise((resolve) => {
    const headers = { 'content-type': 'application/json' };
    if (!chunked) headers['content-length'] = String(payload.length);
    const req = http.request({ host: '127.0.0.1', port: 8231, path, method: 'POST', headers }, (res) => {
      const parts = [];
      res.on('data', (c) => parts.push(c));
      res.on('end', () => resolve({ ok: true, status: res.statusCode, headers: res.headers, body: Buffer.concat(parts).toString() }));
    });
    req.on('error', (e) => resolve({ ok: false, error: e.code || e.message }));
    if (splitAt === undefined) {
      req.write(payload);
    } else {
      req.write(payload.subarray(0, splitAt));
      req.write(payload.subarray(splitAt));
    }
    req.end();
  });
}

const j = (o) => Buffer.from(JSON.stringify(o));
// 构造恰好 target 字节的合法商品 JSON
function exactSizedProduct(target) {
  const base = { name: '大商品', specs: [{ attributes: [{ name: '颜色', value: '' }], price: '10.00', stock: 1 }] };
  const b = JSON.stringify(base);
  const pad = target - Buffer.byteLength(b);
  const fill = '"' + 'a'.repeat(pad - 2);
  // 把填充放进属性值字符串里
  const obj = { name: '大商品', specs: [{ attributes: [{ name: '颜色', value: 'a'.repeat(pad - 2) }], price: '10.00', stock: 1 }] };
  const got = Buffer.byteLength(JSON.stringify(obj));
  if (got !== target) throw new Error(`size mismatch ${got} != ${target}`);
  return Buffer.from(JSON.stringify(obj));
}

// 1. 超限：整包 + content-length
let r = await rawRequest('/api/products', Buffer.from('x'.repeat(LIMIT + 1)));
console.log('1 over-limit oneshot:', r.ok && r.status, JSON.parse(r.body).error.slice(0, 30), 'conn=', r.headers.connection);

// 2. 超限：chunked
r = await rawRequest('/api/products', Buffer.from('x'.repeat(LIMIT + 1)), { chunked: true });
console.log('2 over-limit chunked:', r.ok && r.status, JSON.parse(r.body).error.slice(0, 30));

// 3. 超限：多段 data（在 100 字节处切分），content-length 预声明
r = await rawRequest('/api/products', Buffer.from('x'.repeat(LIMIT + 100)), { splitAt: 100 });
console.log('3 over-limit split100:', r.ok && r.status, JSON.parse(r.body).error.slice(0, 20));

// 4. 超限 + 非法 JSON，结果仍必须是“超限”
r = await rawRequest('/api/products', Buffer.from('{not json'.padEnd(LIMIT + 10, 'x')));
console.log('4 over + bad json:', r.ok && r.status, JSON.parse(r.body).error.includes('超过') ? 'TOO-LARGE-REASON' : 'WRONG');

// 5. 超限 + 合法 JSON 但售价非法，结果仍必须是“超限”
const badPrice = { name: 'n', specs: [{ attributes: [{ name: 'a', value: 'b' }], price: '-1', stock: 1, pad: 'x'.repeat(LIMIT) }] };
r = await rawRequest('/api/products', j(badPrice));
console.log('5 over + bad price:', r.ok && r.status, JSON.parse(r.body).error.includes('超过') ? 'TOO-LARGE-REASON' : 'WRONG', JSON.parse(r.body).details ? 'HAS-DETAILS?' : 'no-details');

// 6. 恰好等于上限的合法请求 -> 进入正常流程 -> 201
const exact = exactSizedProduct(LIMIT);
r = await rawRequest('/api/products', exact);
console.log('6 exactly-limit valid:', r.ok && r.status, r.status === 201 ? '201' : r.body.slice(0, 80));

// 7. 恰好上限 + 1 但合法 -> 400 超限
const obj7 = JSON.parse(exact.toString());
obj7.specs[0].attributes[0].value += 'b'; // 多一个 ASCII 字节
r = await rawRequest('/api/products', j(obj7));
console.log('7 limit+1 valid-json:', r.ok && r.status, JSON.parse(r.body).error.includes('超过') ? 'TOO-LARGE-REASON' : 'WRONG');

// 8. 中文内容超限同样按字节
const zh = { name: '中文商品', specs: [{ attributes: [{ name: '属性', value: '中'.repeat(200000) }], price: '1.00', stock: 0 }] };
r = await rawRequest('/api/products', j(zh));
console.log('8 chinese over-limit:', r.ok && r.status, JSON.parse(r.body).error.includes('超过') ? 'TOO-LARGE-REASON' : 'WRONG');

// 9. 中文内容恰好不超：200000 个中文字符约 600000 字节，整体应 201
const zh2 = { name: '中文商品', specs: [{ attributes: [{ name: '属性', value: '中'.repeat(150000) }], price: '1.00', stock: 0 }] };
r = await rawRequest('/api/products', j(zh2));
console.log('9 chinese under-limit:', r.ok && r.status, Buffer.byteLength(j(zh2)), r.status === 201 ? '201' : r.body.slice(0, 60));

// 10. 列表检查：只有 #6 和 #9 两个商品；超限的都没落盘
const list = await new Promise((resolve) => {
  http.get('http://127.0.0.1:8231/api/products', (res) => {
    let b = ''; res.on('data', (c) => b += c); res.on('end', () => resolve(JSON.parse(b).products));
  });
});
console.log('10 list count:', list.length, '(expect 2)');

// 11. 处理过超限请求后仍能正常新增一件合法小商品
r = await rawRequest('/api/products', j({ name: '新商品', specs: [{ attributes: [{ name: '颜色', value: '红' }], price: '3.5', stock: 7 }] }));
console.log('11 normal after over-limit:', r.ok && r.status, r.status === 201 ? '201' : r.body.slice(0,80), 'price=', r.status===201 && JSON.parse(r.body).specs[0].price);

// 12. 普通非法 JSON（不超限）仍返回原有提示
r = await rawRequest('/api/products', Buffer.from('{oops}'));
console.log('12 bad json under-limit:', r.ok && r.status, JSON.parse(r.body).error);

// 13. 字段不合规仍返回 details
r = await rawRequest('/api/products', j({ name: 'n', specs: [{ attributes: [{ name: 'a', value: 'b' }], price: 'bad', stock: 1 }] }));
console.log('13 field invalid:', r.ok && r.status, JSON.parse(r.body).details?.[0]?.field, JSON.parse(r.body).details?.[0]?.specIndex);
EOF
